async function uploadBackgroundPhoto(){const input=$('#backgroundPhotoInput'),file=input?.files?.[0],btn=$('#uploadBackgroundPhotoBtn');if(!file)return flash('Kies eerst een JPG, PNG of WebP.','error');if(file.size>15*1024*1024)return flash('Foto is groter dan 15 MB. Kies een kleinere afbeelding.','error');btn.disabled=true;btn.textContent='Uploaden…';try{const d=await api('/api/background/upload',{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream','X-File-Name':encodeURIComponent(file.name||'background')},body:file,timeoutMs:45000});settings.backgroundPhotoVersion=Number(d.version)||Date.now();$('#backgroundStyleInput').value='photo';toggleBackgroundColor();const saved=await api('/api/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(formToSettings())});renderSettings(saved.settings||formToSettings());flash('Achtergrondfoto opgeslagen ✓','ok');await backgroundPhotoInfo()}catch(e){flash(`Foto opslaan mislukt: ${e.message}`,'error')}finally{btn.disabled=false;btn.textContent='Foto opslaan'}}
