async function uploadDispatchTune(){const input=$('#dispatchTuneFileInput'),file=input?.files?.[0],btn=$('#uploadDispatchTuneBtn');if(!file)return flash('Kies eerst een MP3, WAV of OGG.','error');if(file.size>12*1024*1024)return flash('Deuntje is groter dan 12 MB.','error');btn.disabled=true;btn.textContent='Uploaden…';try{const d=await api('/api/tune/upload',{method:'POST',headers:{'Content-Type':file.type||'application/octet-stream','X-File-Name':encodeURIComponent(file.name||'deuntje')},body:file,timeoutMs:45000});settings.dispatchTuneCustomVersion=Number(d.version)||Date.now();await saveTuneSettings({silent:true});flash('Eigen deuntje opgeslagen ✓','ok');await tuneFileInfo()}catch(e){flash(`Deuntje opslaan mislukt: ${e.message}`,'error')}finally{btn.disabled=false;btn.textContent='Eigen deuntje opslaan'}}
