function testToken(kind){return `${kind}-${Date.now()}-${Math.random().toString(36).slice(2,9)}`}
async function waitForTestResult(token,timeoutMs=12000){const until=Date.now()+timeoutMs;while(Date.now()<until){await new Promise(r=>setTimeout(r,350));try{const d=await api(`/api/test-status?token=${encodeURIComponent(token)}`),result=d.result||{};if(result.status==='completed'||result.status==='error')return result}catch{}}throw new Error('Geen afspeelbevestiging van de lichtkrant ontvangen')}
async function persistCurrentSettings(){const d=await api('/api/settings',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(formToSettings())});renderSettings(d.settings||formToSettings());return d.settings||settings}
async function testDispatchTune(){const b=$('#testDispatchTuneBtn');b.disabled=true;try{await saveTuneSettings({silent:true});const token=testToken('tune'),choice=$('#dispatchTuneDefaultInput').value||'none';flash('Deuntje op lichtkrant testen…');await api('/api/test-message',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({token,mode:'tune-only',service:'brandweer',priority:'P1',speak:false,force_audio:true,tune_choice:choice})});const result=await waitForTestResult(token,18000);flash(result.ok?`Deuntje werkt ✓ ${result.detail||''}`:`Deuntjetest mislukt: ${result.detail||'onbekende fout'}`,result.ok?'ok':'error')}catch(e){flash(`Deuntjetest mislukt: ${e.message}`,'error')}finally{b.disabled=false}}
async function status(){try{const d=await api('/api/status');setText('#versionStatus',d.version);setText('#feedStatus',d.feed_status||'—');setText('#todayStatus',d.messages_today??0);setText('#lastMessageStatus',d.last_message?new Date(d.last_message).toLocaleString('nl-NL'):'nog geen');setText('#scopeStatus',d.scope);setText('#errorStatus',d.last_error||'geen');setText('#quickFeedStatus',d.feed_status||'—');const p=$('#controlStatus');p.textContent=d.feed_status==='online'?'online':(d.feed_status||'onbekend');p.className='status-pill '+(d.feed_status==='online'?'online':'error');if(d.supervisor)renderSupervisor(d.supervisor)}catch(e){setText('#controlStatus','offline');$('#controlStatus').className='status-pill error';setText('#quickFeedStatus','offline');setText('#errorStatus',e.message)}}
async function feeds(){try{const [d,h]=await Promise.all([api('/api/feed-config'),api('/api/health')]),cfg=d.config||{},metrics=h.health?.feed_metrics||[],metric=new Map(metrics.map(x=>[x.url,x]));if($('#feed112nuInput'))$('#feed112nuInput').checked=cfg.feed_112nu_enabled!==false;const groups=[['HOOFD • 112-NU',cfg.primary_feed_urls||[]],['RACE/FALLBACK',cfg.race_feed_urls||[]],['EXTRA',cfg.supplemental_feed_urls||[]],['FALLBACK',cfg.fallback_feed_urls||[]]];const rows=[];for(const [role,urls] of groups)for(const u of urls){const m=metric.get(u)||{},lat=m.latency_p50_seconds==null?'—':`${Number(m.latency_p50_seconds).toFixed(1)}s`,fetch=m.fetch_p50_ms==null?'—':`${Math.round(m.fetch_p50_ms)}ms`;rows.push(`<div class="feed-row"><b>${role}</b> • ${escapeHtml(m.status||'wachten')} • fetch ${fetch} • bronvertraging ${lat} • wins ${Number(m.wins)||0}<br><code>${escapeHtml(u)}</code></div>`)}$('#feedList').innerHTML=rows.join('')||'<div class="feed-row">Geen feeds ingesteld</div>'}catch(e){$('#feedList').textContent=e.message}}
async function save112NuToggle(){const el=$('#feed112nuInput');if(el){el.checked=true;el.disabled=true}}
async function reconnect(){const b=$('#reconnectBtn');b.disabled=true;b.textContent='Herverbinden…';try{await api('/api/feeds/reconnect',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});b.textContent='Aangevraagd ✓';setTimeout(status,1200)}catch{b.textContent='Mislukt'}setTimeout(()=>{b.disabled=false;b.textContent='Feeds opnieuw verbinden'},1800)}
async function displayInfo(){
  try{
    const d=await api('/api/display/info'),x=d.display||{},rows=Array.isArray(x.monitors)?x.monitors:[],sel=$('#kioskMonitorInput');
    // Backend is source of truth. Using the local DEFAULTS value here caused a
    // race where a saved second monitor was silently reset to primary.
    const wanted=String(x.selected_monitor_id||settings.kioskMonitor||'primary');
    const valueOf=r=>String(r.selector||r.device||r.fingerprint||r.id||'primary');
    if(sel&&rows.length){
      sel.innerHTML=rows.map((r,i)=>`<option value="${escapeHtml(valueOf(r)||String(i+1))}">${escapeHtml(r.label||`Scherm ${i+1}`)}${Number.isFinite(r.x)&&Number.isFinite(r.y)?` • ${r.x},${r.y}`:''}</option>`).join('');
      let chosen=rows.find(r=>[r.selector,r.fingerprint,r.device,r.id].map(v=>String(v||'')).includes(wanted));
      if(chosen){
        sel.value=valueOf(chosen);
        settings.kioskMonitor=sel.value;
        setText('#kioskMonitorHint',`Actief: ${chosen.label||sel.value} • positie ${chosen.x},${chosen.y}. Een nieuwe keuze wordt direct toegepast en de kiosk opnieuw geplaatst.`);
      }else if(wanted&&!['primary','primair','auto'].includes(wanted.toLowerCase())){
        // Preserve a stable monitor fingerprint when HDMI/DP is temporarily
        // disconnected; otherwise saving an unrelated setting loses the choice.
        const opt=document.createElement('option');opt.value=wanted;opt.textContent='Opgeslagen scherm • momenteel niet aangesloten';sel.prepend(opt);sel.value=wanted;
        settings.kioskMonitor=wanted;
        setText('#kioskMonitorHint','Het opgeslagen scherm is momenteel niet gevonden. De keuze blijft bewaard en wordt gebruikt zodra het scherm terug is.');
      }else{
        chosen=rows.find(r=>r.primary)||rows[0];sel.value=valueOf(chosen);settings.kioskMonitor=sel.value;
      }
    }
    const e=$('#displayStatus'),platform=x.platform==='linux'?`Linux ${x.session||''}`.trim():(x.platform==='windows'?'Windows':(x.platform||'systeem'));
    e.textContent=x.connected?`${rows.length||1} scherm${rows.length===1?'':'en'} • ${platform}${x.method?' • '+x.method:''}`:`${platform} • detectie beperkt`;
    e.className='status-pill '+(x.connected?'online':(rows.length?'':'error'));
    return x;
  }catch(e){setText('#displayStatus','fout');throw e}
}
async function applyDisplaySelection(){
  const sel=$('#kioskMonitorInput'),btn=$('#applyDisplayBtn'),selector=sel?.value||'primary';
  if(btn){btn.disabled=true;btn.textContent='Verplaatsen…'}
  try{
    const d=await api('/api/display/select',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({selector})});
    settings={...settings,...(d.settings||{}),kioskMonitor:d.selector||selector};
    const m=d.selected_monitor||{};
    flash(`Lichtkrant verplaatst naar ${m.label||m.device||'gekozen scherm'} ✓`,'ok');
    setTimeout(()=>displayInfo().catch(()=>{}),900);
    return d;
  }catch(e){flash(`Scherm wisselen mislukt: ${e.message}`,'error');await displayInfo().catch(()=>{})}
  finally{if(btn){btn.disabled=false;btn.textContent='Nu toepassen'}}
}
