async function vehicleDb(){
  try{
    const s=await api('/api/vehicles/status'),st=s.status||{},regions=st.selected_regions||[],cached=(st.cached_regions||[]).filter(x=>x!=='sw-api');
    const sw=st.sw_api||{};renderSwApiStatus(sw);
    const rows=Object.entries(st.regions||{}),done=rows.filter(([,x])=>x?.ok).length;
    setText('#vehicleCount',st.count??'—');setText('#vehicleVersion',st.version||'4.4.15');
    const busy=st.running||st.force_pending;
    setText('#vehicleRegionStatus',busy?`bijwerken… (${Math.max(done,cached.length)}/${regions.length})`:(regions.length?`${Math.max(done,cached.length)}/${regions.length} regio’s`:'geen BRW-regio'));
    const detail=$('#vehicleSyncDetail');
    if(detail){
      if(sw.last_error&&!sw.key_valid){detail.textContent=`SW API: ${String(sw.last_error).slice(0,320)} • lokale cache blijft actief${sw.unit_count?` (${sw.unit_count} eenheden)`:''}`;detail.dataset.kind='error'}
      else if(sw.key_valid){detail.textContent=`SW Mediaproducties API online • ${sw.unit_count||0} eenheden • ${sw.pages||'?'} pagina('s) • sync ${shortDateTime(sw.last_sync)}`;detail.dataset.kind='ok'}
      else if(st.last_error){detail.textContent=`Fallback-fout: ${String(st.last_error).slice(0,420)}`;detail.dataset.kind='error'}
      else if(rows.length){
        detail.textContent=rows.map(([code,x])=>`${code}: ${x?.count??0} voertuigen${x?.source?' • '+x.source:''}${x?.cached?' • cache':''}${x?.pages>1?' • '+x.pages+' pagina’s':''}`).join('  |  ');detail.dataset.kind='ok';
      }else if(cached.length){
        const meta=st.region_meta||{};detail.textContent=cached.map(code=>`${code}: ${meta[code]?.count??'?'} voertuigen${meta[code]?.source?' • '+meta[code].source:''} • cache`).join('  |  ');detail.dataset.kind='ok';
      }else{detail.textContent=regions.length?'Nog geen regionale fallbackcache. Klik op Nu synchroniseren.':'Geen brandweerregio geselecteerd.';detail.dataset.kind=''}
    }
    return st;
  }catch(e){setText('#vehicleCount','fout');setText('#vehicleRegionStatus',e.message);const d=$('#vehicleSyncDetail');if(d){d.textContent=e.message;d.dataset.kind='error'};throw e}
}
async function syncVehicles(){
  const b=$('#syncVehiclesBtn');b.disabled=true;b.textContent='Bijwerken…';
  try{
    await api('/api/vehicles/sync',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({force:true}),timeoutMs:60000});
    let st=null;
    for(let i=0;i<80;i++){await new Promise(r=>setTimeout(r,750));st=await vehicleDb();if(!st.running&&!st.force_pending)break}
    st=await vehicleDb();
    if(st.running||st.force_pending){b.textContent='Nog bezig…';flash('Voertuigendatabase werkt nog op de achtergrond bij.','')}
    else if(st.last_error){b.textContent='Mislukt';flash(`Voertuigendatabase: ${st.last_error}`,'error')}
    else{b.textContent='Bijgewerkt ✓';const sw=st.sw_api||{};flash(sw.key_valid?`SW Roepnummer API bijgewerkt: ${sw.unit_count||0} eenheden • ${st.count} totaal bekend.`:`Voertuigendatabase bijgewerkt: ${st.count} bekende voertuigen.`,'ok')}
  }catch(e){b.textContent='Mislukt';flash(`Voertuigendatabase: ${e.message}`,'error')}
  setTimeout(()=>{b.disabled=false;b.textContent='Nu synchroniseren'},2400)
}
