function renderGithubSettingsStatus(st={}){const state=String(st.state||'idle'),pill=$('#githubSettingsStatusPill');setText('#githubSettingsState',state);setText('#githubSettingsRevision',st.revision||'—');setText('#githubSettingsCheckedAt',st.updated_at?new Date(st.updated_at).toLocaleString('nl-NL'):'—');setText('#githubSettingsAppliedKeys',Array.isArray(st.applied_keys)?`${st.applied_keys.length} velden`:'—');setText('#githubSettingsDetail',st.error?`Fout: ${st.error}`:(st.message||'Nog niet gecontroleerd.'));if(pill){const err=state==='error';pill.textContent=err?'fout':state==='applied'?'toegepast':state==='up-to-date'?'actueel':state;pill.className='status-pill '+(err?'error':state==='applied'||state==='up-to-date'?'online':'')}}
async function githubSettingsStatus(){try{const d=await api('/api/github/settings-sync/status');renderGithubSettingsStatus(d.status||{})}catch(e){setText('#githubSettingsStatusPill','offline');setText('#githubSettingsDetail',e.message)}}
async function saveGithubSettingsSync(){const b=$('#saveGithubSettingsBtn');b.disabled=true;try{const payload={github_settings_auto_sync:$('#githubSettingsAutoSyncInput').checked,github_settings_path:($('#githubSettingsPathInput').value||'').trim(),github_settings_branch:($('#githubSettingsBranchInput').value||'main').trim(),github_settings_minutes:Number($('#githubSettingsMinutesInput').value)||5};const d=await api('/api/github/settings-sync/config',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});renderGithubSettingsSyncConfig(d.config||payload);flash('GitHub-instellingensynchronisatie opgeslagen ✓','ok');setTimeout(githubSettingsStatus,900)}catch(e){flash(`Synchronisatie opslaan: ${e.message}`,'error')}finally{b.disabled=false}}
async function pullGithubSettings(){const b=$('#pullGithubSettingsBtn');b.disabled=true;b.textContent='Ophalen…';try{const d=await api('/api/github/settings-sync/pull',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}',timeoutMs:45000});renderGithubSettingsStatus(d.status||{});if(d.settings)renderSettings(d.settings);flash('Instellingen vanaf GitHub toegepast ✓','ok')}catch(e){flash(`GitHub-instellingen: ${e.message}`,'error');await githubSettingsStatus()}finally{b.disabled=false;b.textContent='Nu ophalen en toepassen'}}
async function loadSetup(){try{const d=await api('/api/setup');setupProfile=d.setup||{};const regionMeta=new Map((setupProfile.regions||[]).map(r=>[r.slug,r]));const selected=Object.keys(setupProfile.region_disciplines||{});const tags=selected.map(slug=>regionMeta.get(slug)?.label||slug);$('#scopeTags').innerHTML=tags.map(x=>`<span>${escapeHtml(x)}</span>`).join('')||'<span>Nog niet ingesteld</span>';const owner=setupProfile.profile_type==='bedrijf'?(setupProfile.company_name||'Bedrijf'):(setupProfile.person_name||'Particulier');$('#profileTitle').textContent=(setupProfile.standplaats_city||setupProfile.standplaats)?`Standplaats ${setupProfile.standplaats_city||setupProfile.standplaats}`:'Installatieprofiel';$('#profileSummary').textContent=`${owner} • ${selected.length} regio${selected.length===1?'':'’s'} • ${(setupProfile.feed_urls||[]).length} RSS-bronnen. Wijzig regio’s en disciplines via de Configuratiewizard.`;$('#profileBadge').textContent=setupProfile.profile_type==='bedrijf'?'BEDRIJF':'PARTICULIER';const t=$('#testInput');if(t&&t.dataset.autoExample!=='0'){const place=setupProfile.standplaats_city||setupProfile.standplaats||'Utrecht';t.value=`P 1 BR woning Hoofdstraat ${place}`;t.dataset.autoExample='1';}}catch(e){$('#profileSummary').textContent=`Installatieprofiel laden mislukt: ${e.message}`}}
function renderIdleBuilderPreview(){const box=$('#idleBuilderPreview');if(!box)return;const layout=$('#idleLayoutInput')?.value||settings.idleLayout||'center',headline=($('#idleHeadlineInput')?.value||settings.idleHeadline||settings.name||'P2000 Monitor').trim(),sub=($('#idleSublineInput')?.value||settings.idleSubline||'P2000 MELDINGEN HEBBEN DIRECT VOORRANG').trim(),scale=clamp($('#idleClockScaleInput')?.value||settings.idleClockScale,65,135,100),showName=$('#idleShowNameInput')?.checked!==false,showDate=$('#idleShowDateInput')?.checked!==false,showSeconds=$('#idleShowSecondsInput')?.checked!==false,showStatus=$('#idleShowStatusInput')?.checked!==false,now=new Date();box.dataset.layout=layout;box.querySelector('.idle-preview-name').textContent=showName?(headline||settings.name||'P2000 Monitor'):'';box.querySelector('.idle-preview-time').innerHTML=`${String(now.getHours()).padStart(2,'0')}:${String(now.getMinutes()).padStart(2,'0')}${showSeconds?`<small>${String(now.getSeconds()).padStart(2,'0')}</small>`:''}`;box.querySelector('.idle-preview-time').style.fontSize=`${Math.round(2.45*scale/100)}rem`;box.querySelector('.idle-preview-date').textContent=showDate?now.toLocaleDateString('nl-NL',{weekday:'long',day:'2-digit',month:'long',year:'numeric'}).toUpperCase():'';box.querySelector('.idle-preview-status').textContent=showStatus?sub:'';}
function escapeHtml(s){return String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
