  $('#saveBtn').addEventListener('click',save);$('#dispatchTuneVolumeInput')?.addEventListener('input',()=>{updateTuneVolumeLabel();scheduleTuneSave()});for(const id of ['#dispatchTuneEnabledInput','#dispatchTuneDefaultInput','#dispatchTuneBrandweerInput','#dispatchTuneAmbulanceInput','#dispatchTunePolitieInput','#dispatchTuneLifelinerInput','#dispatchTuneKnrmInput','#dispatchTuneUrgentInput','#dispatchTuneYoutubeUrlInput','#dispatchTuneYoutubeSecondsInput'])$(id)?.addEventListener('change',scheduleTuneSave);$('#saveTuneSettingsBtn')?.addEventListener('click',()=>saveTuneSettings());$('#uploadDispatchTuneBtn')?.addEventListener('click',uploadDispatchTune);$('#removeDispatchTuneBtn')?.addEventListener('click',removeDispatchTune);$('#testDispatchTuneBtn')?.addEventListener('click',testDispatchTune);$('#backgroundStyleInput').addEventListener('change',toggleBackgroundColor);$('#uploadBackgroundPhotoBtn')?.addEventListener('click',uploadBackgroundPhoto);$('#removeBackgroundPhotoBtn')?.addEventListener('click',removeBackgroundPhoto);$('#reconnectBtn').addEventListener('click',reconnect);$('#detectDisplayBtn').addEventListener('click',()=>displayInfo().catch(()=>{}));$('#kioskMonitorInput')?.addEventListener('change',applyDisplaySelection);$('#applyDisplayBtn')?.addEventListener('click',applyDisplaySelection);$('#displayOffBtn').addEventListener('click',()=>displayPower('off'));$('#displayOnBtn').addEventListener('click',()=>displayPower('on'));$('#testDisplayBtn').addEventListener('click',()=>testMessage(false));$('#testSpeakBtn').addEventListener('click',()=>testMessage(true));$('#voiceTestBtn').addEventListener('click',voiceTest);$('#stopSpeechBtn').addEventListener('click',stopSpeech);$('#refreshUnknownBtn').addEventListener('click',unknown);$('#syncVehiclesBtn').addEventListener('click',syncVehicles);$('#saveSwApiKeyBtn')?.addEventListener('click',saveSwApiKey);$('#clearSwApiKeyBtn')?.addEventListener('click',clearSwApiKey);$('#saveVehicleOverrideBtn')?.addEventListener('click',saveVehicleOverride);$('#resetVehicleOverrideBtn')?.addEventListener('click',resetVehicleOverrideForm);$('#vehicleOverrideList')?.addEventListener('click',e=>{const edit=e.target.closest('[data-override-edit]'),del=e.target.closest('[data-override-delete]');if(edit)editVehicleOverride(edit.dataset.overrideEdit);if(del)deleteVehicleOverride(del.dataset.overrideDelete)});$('#unknownList')?.addEventListener('click',e=>{const b=e.target.closest('[data-unknown-callsign]');if(b)prefillVehicleOverride(b.dataset.unknownCallsign)});$('#saveUpdateSettingsBtn')?.addEventListener('click',saveUpdateSettings);$('#checkUpdateBtn')?.addEventListener('click',()=>checkGithubUpdate(false));$('#installUpdateBtn')?.addEventListener('click',()=>checkGithubUpdate(true));$('#rollbackUpdateBtn')?.addEventListener('click',rollbackUpdate);$('#saveGithubSettingsBtn')?.addEventListener('click',saveGithubSettingsSync);$('#pullGithubSettingsBtn')?.addEventListener('click',pullGithubSettings);
  Promise.allSettled([loadSetup(),loadSettings(),loadGithubUpdateSettings(),updateStatus(),loadGithubSettingsSyncConfig(),githubSettingsStatus(),status(),feeds(),displayInfo(),tts(),loadSwApiConfig(),vehicleDb(),loadVehicleOverrides(),unknown(),vehicleHistory(),supervisorStatus(),quickDetails()]).then(livePreview);setInterval(status,15000);setInterval(supervisorStatus,15000);setInterval(quickDetails,15000);setInterval(feeds,30000);setInterval(updateStatus,30000);setInterval(githubSettingsStatus,30000);setInterval(unknown,30000);setInterval(tts,30000);setInterval(vehicleDb,60000);
